import {
  AUDIBLE_LEAD_MAX_MS,
  AUDIBLE_OVER_FLOOR_DB,
  AUDIBLE_TAIL_MAX_MS,
  FORCE_CUT_LOOKBACK_MS,
  FRAME_MS,
  FRAME_SAMPLES,
  GAP_MS,
  INITIAL_NOISE_FLOOR_DB,
  LONG_PAUSE_MS,
  MAX_CHUNK_MS,
  MIN_SPEECH_MS,
  NOISE_FLOOR_FALL,
  NOISE_FLOOR_MAX_DB,
  NOISE_FLOOR_MIN_DB,
  NOISE_FLOOR_RISE,
  NOISE_WINDOW_MS,
  PAUSE_MIN_AUDIO_MS,
  PAUSE_MS,
  PRE_ROLL_MS,
  SAMPLE_RATE,
  STOP_TAIL_PAD_MS,
  TAIL_KEEP_MS,
  TARGET_CHUNK_MS,
  TRAILING_SILENCE_MS,
  VOICED_ABS_DB,
  VOICED_OVER_FLOOR_DB,
} from "./constants.js";
import { concatInt16 } from "./pcm.js";
export const DEFAULT_SPEECH_CHUNKER_CONFIG = {
  sampleRate: SAMPLE_RATE,
  frameMs: FRAME_MS,
  noiseFloorMinDb: NOISE_FLOOR_MIN_DB,
  noiseFloorMaxDb: NOISE_FLOOR_MAX_DB,
  noiseFloorFall: NOISE_FLOOR_FALL,
  noiseFloorRise: NOISE_FLOOR_RISE,
  voicedAbsDb: VOICED_ABS_DB,
  voicedOverFloorDb: VOICED_OVER_FLOOR_DB,
  audibleOverFloorDb: AUDIBLE_OVER_FLOOR_DB,
  audibleLeadMaxMs: AUDIBLE_LEAD_MAX_MS,
  audibleTailMaxMs: AUDIBLE_TAIL_MAX_MS,
  initialNoiseFloorDb: INITIAL_NOISE_FLOOR_DB,
  preRollMs: PRE_ROLL_MS,
  trailingSilenceMs: TRAILING_SILENCE_MS,
  tailKeepMs: TAIL_KEEP_MS,
  stopTailPadMs: STOP_TAIL_PAD_MS,
  minSpeechMs: MIN_SPEECH_MS,
  pauseMs: PAUSE_MS,
  pauseMinAudioMs: PAUSE_MIN_AUDIO_MS,
  longPauseMs: LONG_PAUSE_MS,
  targetChunkMs: TARGET_CHUNK_MS,
  gapMs: GAP_MS,
  maxChunkMs: MAX_CHUNK_MS,
  forceCutLookbackMs: FORCE_CUT_LOOKBACK_MS,
  noiseWindowMs: NOISE_WINDOW_MS,
};
const SILENT_DB = -100;
export class SpeechChunker {
  config;
  frameSamples;
  carry = new Int16Array(0);
  frames = [];
  recentDbs = [];
  noiseFloorDb;
  silenceRunMs = 0;
  sessionMs = 0;
  totalSpeechMs = 0;
  openSpeechMs = 0;
  hasSpeech = false;
  hasAudible = false;
  live;
  constructor(config = {}) {
    this.config = { ...DEFAULT_SPEECH_CHUNKER_CONFIG, ...config };
    this.frameSamples =
      Math.round((this.config.sampleRate * this.config.frameMs) / 1000) ||
      FRAME_SAMPLES;
    this.noiseFloorDb = this.config.initialNoiseFloorDb;
    this.live = this.buildLive(SILENT_DB, false);
  }
  getLive() {
    return this.live;
  }
  push(pcm) {
    if (pcm.length === 0) return [];
    const incoming = concatInt16([this.carry, pcm]);
    const closed = [];
    let offset = 0;
    while (offset + this.frameSamples <= incoming.length) {
      const frame = incoming.subarray(offset, offset + this.frameSamples);
      offset += this.frameSamples;
      const result = this.pushFrame(frame, true);
      if (result) closed.push(result);
    }
    this.carry = incoming.slice(offset);
    return closed;
  }
  flush() {
    if (this.carry.length > 0) {
      const padded = new Int16Array(this.frameSamples);
      padded.set(this.carry);
      this.carry = new Int16Array(0);
      this.pushFrame(padded, false);
    }
    return this.closeAtStop();
  }
  pushFrame(pcm, allowCut) {
    const levelDb = rmsDb(pcm);
    const voiced = levelDb > this.voicedThresholdDb();
    const audible = levelDb > this.audibleThresholdDb();
    this.updateNoiseFloor(levelDb, voiced);
    this.sessionMs += this.config.frameMs;
    if (voiced) {
      this.totalSpeechMs += this.config.frameMs;
      this.openSpeechMs += this.config.frameMs;
      this.silenceRunMs = 0;
      this.hasSpeech = true;
    } else {
      this.silenceRunMs += this.config.frameMs;
    }
    if (audible) this.hasAudible = true;
    this.frames.push({ pcm: pcm.slice(), db: levelDb, voiced, audible });
    this.trimPreRoll();
    this.compactTrailingSilence();
    this.live = this.buildLive(levelDb, voiced);
    if (!allowCut) return undefined;
    return this.maybeClose();
  }
  voicedThresholdDb() {
    return Math.max(
      this.config.voicedAbsDb,
      this.noiseFloorDb + this.config.voicedOverFloorDb
    );
  }
  audibleThresholdDb() {
    return Math.max(
      this.config.voicedAbsDb,
      this.noiseFloorDb + this.config.audibleOverFloorDb
    );
  }
  updateNoiseFloor(levelDb, voiced) {
    this.recentDbs.push(levelDb);
    const windowFrames = Math.max(
      1,
      Math.round(this.config.noiseWindowMs / this.config.frameMs)
    );
    if (this.recentDbs.length > windowFrames)
      this.recentDbs = this.recentDbs.slice(-windowFrames);
    if (voiced) {
      const quietest = Math.min(...this.recentDbs);
      this.noiseFloorDb +=
        this.config.noiseFloorRise * (quietest - this.noiseFloorDb);
    } else {
      this.noiseFloorDb +=
        this.config.noiseFloorFall * (levelDb - this.noiseFloorDb);
    }
    this.noiseFloorDb = Math.min(
      this.config.noiseFloorMaxDb,
      Math.max(this.config.noiseFloorMinDb, this.noiseFloorDb)
    );
  }
  // No speech yet, so keep only a short lead-in: `preRollMs` of silence, or `audibleLeadMaxMs`
  // once something audible arrived. A soft first word survives, room noise cannot pile up.
  trimPreRoll() {
    if (this.hasSpeech) return;
    const leadMs = this.hasAudible
      ? this.config.audibleLeadMaxMs
      : this.config.preRollMs;
    const maxFrames = Math.round(leadMs / this.config.frameMs);
    if (this.frames.length > maxFrames) {
      this.frames = this.frames.slice(this.frames.length - maxFrames);
    }
  }
  // After the last voiced frame keep `audibleTailMaxMs` untouched (soft trailing words live
  // there), then only the newest `trailingSilenceMs`, so a long quiet run cannot grow the chunk.
  compactTrailingSilence() {
    if (!this.hasSpeech) return;
    const protectedFrames = Math.round(
      this.config.audibleTailMaxMs / this.config.frameMs
    );
    const maxQuietFrames = Math.round(
      this.config.trailingSilenceMs / this.config.frameMs
    );
    const unvoiced = trailingUnvoicedFrames(this.frames);
    const excess = unvoiced - protectedFrames - maxQuietFrames;
    if (excess <= 0) return;
    const cut = this.frames.length - unvoiced + protectedFrames;
    this.frames = [
      ...this.frames.slice(0, cut),
      ...this.frames.slice(cut + excess),
    ];
  }
  maybeClose() {
    const openAudioMs = this.frames.length * this.config.frameMs;
    if (openAudioMs >= this.config.maxChunkMs) return this.closeAtQuietest();
    // Not enough speech to cut. Keep it open so it rides along with the next chunk.
    if (!this.hasSpeech || this.openSpeechMs < this.config.minSpeechMs)
      return undefined;
    if (this.silenceRunMs >= this.config.longPauseMs)
      return this.closeWithTail("pause");
    if (
      this.silenceRunMs >= this.config.pauseMs &&
      openAudioMs >= this.config.pauseMinAudioMs
    ) {
      return this.closeWithTail("pause");
    }
    if (
      openAudioMs >= this.config.targetChunkMs &&
      this.silenceRunMs >= this.config.gapMs
    ) {
      return this.closeWithTail("gap");
    }
    return undefined;
  }
  closeWithTail(reason) {
    const tailFrames = Math.round(this.config.tailKeepMs / this.config.frameMs);
    const lastAudible = lastAudibleIndex(this.frames);
    const end = Math.min(this.frames.length, lastAudible + 1 + tailFrames);
    return this.emit(this.frames.slice(0, end), this.frames.slice(end), reason);
  }
  closeAtQuietest() {
    const lookbackFrames = Math.round(
      this.config.forceCutLookbackMs / this.config.frameMs
    );
    const start = Math.max(0, this.frames.length - lookbackFrames);
    const window = this.frames.slice(start);
    const first = window[0];
    let quietestIndex = start;
    let quietestDb = first.db;
    window.forEach((frame, offset) => {
      const index = start + offset;
      if (
        frame.db < quietestDb ||
        (frame.db === quietestDb && index > quietestIndex)
      ) {
        quietestDb = frame.db;
        quietestIndex = index;
      }
    });
    const end = Math.max(1, quietestIndex + 1);
    return this.emit(this.frames.slice(0, end), this.frames.slice(end), "max");
  }
  // Key released: send every open frame plus a little silence so the recognizer can finish the
  // last word. Always pad, a quiet ending may still be speech the thresholds missed.
  closeAtStop() {
    if (!this.hasAudible) {
      this.resetOpenChunk();
      return undefined;
    }
    const padFrames = Math.round(
      this.config.stopTailPadMs / this.config.frameMs
    );
    const padding = Array.from({ length: padFrames }, () => this.silentFrame());
    return this.emit([...this.frames, ...padding], [], "stop");
  }
  silentFrame() {
    return {
      pcm: new Int16Array(this.frameSamples),
      db: SILENT_DB,
      voiced: false,
      audible: false,
    };
  }
  emit(closedFrames, remaining, reason) {
    const speechMs =
      closedFrames.filter((frame) => frame.voiced).length * this.config.frameMs;
    this.resetOpenChunk(remaining);
    if (!closedFrames.some((frame) => frame.audible)) return undefined;
    return {
      audio: concatInt16(closedFrames.map((frame) => frame.pcm)),
      audioMs: closedFrames.length * this.config.frameMs,
      speechMs,
      reason,
    };
  }
  resetOpenChunk(remaining = []) {
    this.frames = remaining;
    this.hasSpeech = remaining.some((frame) => frame.voiced);
    this.hasAudible = remaining.some((frame) => frame.audible);
    this.openSpeechMs =
      remaining.filter((frame) => frame.voiced).length * this.config.frameMs;
    this.silenceRunMs = trailingSilenceMs(remaining, this.config.frameMs);
    this.live = this.buildLive(this.live.levelDb, this.live.voiced);
  }
  buildLive(levelDb, voiced) {
    return {
      levelDb,
      noiseDb: this.noiseFloorDb,
      thresholdDb: this.voicedThresholdDb(),
      voiced,
      openAudioMs: this.frames.length * this.config.frameMs,
      openSpeechMs: this.openSpeechMs,
      silenceRunMs: this.silenceRunMs,
      sessionMs: this.sessionMs,
      totalSpeechMs: this.totalSpeechMs,
    };
  }
}
function rmsDb(pcm) {
  let sumSquares = 0;
  for (const sample of pcm) {
    const normalized = sample / 32768;
    sumSquares += normalized * normalized;
  }
  const rms = Math.sqrt(sumSquares / pcm.length);
  if (rms <= 0) return SILENT_DB;
  return 20 * Math.log10(rms);
}
function lastAudibleIndex(frames) {
  return frames.reduce(
    (last, frame, index) => (frame.audible ? index : last),
    0
  );
}
function trailingUnvoicedFrames(frames) {
  let count = 0;
  for (let index = frames.length - 1; index >= 0; index -= 1) {
    if (frames[index]?.voiced) break;
    count += 1;
  }
  return count;
}
function trailingSilenceMs(frames, frameMs) {
  return trailingUnvoicedFrames(frames) * frameMs;
}
